using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using TicTacTec.TA.Library;
using Xunit;

namespace fxpa.tests;

/// <summary>
/// Golden-master tests over the TA-Lib catalog.
///
/// Each fixture under tests/golden/Golden was generated by
/// tests/golden/generate_goldens.py from the canonical C TA-Lib (via the
/// python ta-lib bindings) on a fixed seeded price series. The managed
/// port bundled with this repository (src/lib/TA-Lib-Core.dll) must
/// reproduce those values, so a marshalling, port or runtime regression
/// fails loudly here rather than silently on a chart.
///
/// Regenerate the fixtures with:
///   python3 -m venv .venv && .venv/bin/pip install numpy ta-lib
///   .venv/bin/python tests/golden/generate_goldens.py
/// </summary>
public class CatalogGoldenTests
{
    private static string GoldenDir => Path.Combine(System.AppContext.BaseDirectory, "golden");

    private sealed record Inputs(double[] Close, double[] High, double[] Low, double[] Volume, int Count);

    private static Inputs LoadInputs()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(GoldenDir, "inputs.json")));
        var root = doc.RootElement;
        return new Inputs(
            Close: ReadArray(root.GetProperty("close")),
            High: ReadArray(root.GetProperty("high")),
            Low: ReadArray(root.GetProperty("low")),
            Volume: ReadArray(root.GetProperty("volume")),
            Count: root.GetProperty("count").GetInt32());
    }

    private static double[] ReadArray(JsonElement element)
        => element.EnumerateArray().Select(v => v.GetDouble()).ToArray();

    private static JsonDocument Golden(string function)
    {
        var path = Path.Combine(GoldenDir, function + ".json");
        Assert.True(File.Exists(path), $"missing golden fixture: {path}");
        return JsonDocument.Parse(File.ReadAllText(path));
    }

    /// <summary>
    /// Compares one Core.* invocation against its golden fixture: return
    /// code, warm-up index, output length and every element (within the
    /// fixture's tolerance).
    /// </summary>
    private static void Verify(JsonDocument golden, Core.RetCode ret,
                               int begIdx, int nbElement,
                               IReadOnlyDictionary<string, double[]> outputs)
    {
        var root = golden.RootElement;
        Assert.Equal(Core.RetCode.Success, ret);

        int expectedBegIdx = root.GetProperty("outBegIdx").GetInt32();
        double tolerance = root.GetProperty("tolerance").GetDouble();
        Assert.Equal(expectedBegIdx, begIdx);

        var goldenOutputs = root.GetProperty("outputs");
        foreach (var output in goldenOutputs.EnumerateObject())
        {
            Assert.True(outputs.ContainsKey(output.Name),
                $"golden output '{output.Name}' was not produced by this call");
            double[] expected = output.Value.EnumerateArray().Select(v => v.GetDouble()).ToArray();
            double[] actual = outputs[output.Name];

            Assert.Equal(expected.Length, nbElement);

            for (int i = 0; i < expected.Length; i++)
            {
                double value = actual[i]; // outputs are compact: [0, nbElement)
                Assert.False(double.IsNaN(value),
                    $"'{output.Name}' is NaN at [{i}] where the golden value is {expected[i]}");
                Assert.True(Math.Abs(value - expected[i]) <= tolerance,
                    $"'{output.Name}' diverges at [{i}]: expected {expected[i]}, actual {value} (tolerance {tolerance})");
            }
        }
    }

    [Fact]
    public void Sma_matches_c_reference()
    {
        var inputs = LoadInputs();
        using var golden = Golden("SMA");
        double[] outReal = new double[inputs.Count];
        var ret = Core.Sma(0, inputs.Count - 1, inputs.Close, 14,
                           out int begIdx, out int nbElement, outReal);
        Verify(golden, ret, begIdx, nbElement, new Dictionary<string, double[]> { ["outReal"] = outReal });
    }

